def search(n):
    used=[False]*n
    used_diff=[False]*n
    sol=[0]*n
    def backtrack(pos):
        if pos==n:
            return sol.copy()
        for v in range(n):
            if not used[v]:
                if pos==0:
                    used[v]=True; sol[pos]=v
                    res=backtrack(pos+1)
                    if res: return res
                    used[v]=False
                else:
                    d=abs(v-sol[pos-1])
                    if d==0 or d>=n or used_diff[d]: continue
                    used[v]=True; used_diff[d]=True; sol[pos]=v
                    res=backtrack(pos+1)
                    if res: return res
                    used[v]=False; used_diff[d]=False
        return None
    return backtrack(0)

